import fs from 'fs';
import * as $rdf from 'rdflib';

const base = 'http://university.org/ontology/';
const store = $rdf.graph();
$rdf.parse(fs.readFileSync('university_graph.ttl', 'utf8'), store, base, 'text/turtle');

const text = fs.readFileSync(process.argv[2] || 'solution.sparql', 'utf8');
const q = $rdf.SPARQLToQuery(text, false, store, base);
const rows = [];
store.query(q, r => {
  const get = v => { const t = r[v]; return t ? t.value : undefined; };
  const o = {};
  for (const v of q.vars) o[v.value] = get('?' + v.value);
  rows.push(o);
}, undefined, () => false);
console.log(JSON.stringify(rows, null, 1));
EOF
