p='work/sparql_eval.py'
s=open(p).read()
old = s[s.index('def eval_bgp(g, pats, sols):'):s.index('def str_of(t):')]
new = '''def all_pairs(g, pred):
    out = []
    for (subj, p), objs in g.spo.items():
        if p == pred:
            for o in objs:
                out.append((subj, o))
    return sorted(out, key=repr)


def eval_bgp(g, pats, sols):
    for (s, p, o) in pats:
        out = []
        for sol in sols:
            sk = as_const(s, sol)
            pk = as_const(p, sol)
            ok = as_const(o, sol)
            if pk[0] != 'iri':
                raise QueryError('non-IRI predicate unsupported')
            su = sk[0] == 'var'
            ou = ok[0] == 'var'
            if not su and not ou:
                pairs = [(sk, ok)] if ok in g.spo.get((sk, pk), ()) else []
            elif not su:
                pairs = [(sk, x) for x in g.spo.get((sk, pk), ())]
            elif not ou:
                pairs = [(x, ok) for x in g.pos.get((pk, ok), ())]
            else:
                pairs = all_pairs(g, pk)
            for (sv, ov) in pairs:
                new = dict(sol)
                if su:
                    new[s[1]] = sv
                if ou:
                    new[o[1]] = ov
                out.append(new)
        sols = out
        if not sols:
            return []
    return sols


'''
s = s.replace(old, new)
open(p,'w').write(s)
